"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Ink mail Switch: a 2.25rem by 1.25rem track. Off, it is a quiet well behind
 * a translucent edge with a grey knob. On, the track fills with the off-white
 * primary ink and the knob turns black and slides across.
 */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full border border-(--line-strong) bg-input p-px",
        "transition-[background-color,border-color] duration-fast ease-out",
        "hover:data-[unchecked]:border-(--control)",
        focusRing,
        "data-[disabled]:cursor-not-allowed",
        controlChecked,
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-4 rounded-full bg-muted-foreground shadow-(--shadow-thumb)",
          "transition-[translate,background-color] duration-fast ease-out",
          "data-[checked]:translate-x-4 data-[checked]:bg-primary-foreground data-[unchecked]:translate-x-0",
          "data-[disabled]:bg-(--foreground-disabled) data-[disabled]:shadow-none",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
